/**
 * Font registry — the SINGLE source of truth for every user-selectable face
 * (Settings → Appearance).
 *
 * One list drives everything: the `@font-face` block (generated by
 * `displayFontFaceCss`, injected once in the root layout and in the server-
 * rendered share/print shell), the selection modal, and the runtime CSS-var
 * overrides in `FontProvider`. There are FOUR slots that pick from it — the
 * interface, the wordmark, the peer name, and Pages/Notes prose — and one
 * library behind all four, because "which faces exist" and "where a face is
 * used" are different questions and only the second one varies per slot.
 *
 * ── Every face here is a VARIABLE font with at least two axes ────────────────
 *
 * The ranges below are not typed by hand. They are read out of each file's
 * `fvar` table by `scripts/fonts-import.mjs`, which also converts to woff2 and
 * installs into both apps. That matters more than it sounds: a variable face
 * declared as a single weight makes the browser SYNTHESISE bold, which shows up
 * across the interface as smeared headings and buttons. Add a face by running
 * the importer and pasting its row, never by editing a range by eye.
 *
 * Three axes have real `@font-face` descriptors and are declared per face:
 * `wght` → font-weight, `wdth` → font-stretch, `slnt` → font-style: oblique.
 * A face with a `slnt` axis therefore needs NO italic file: the one file leans
 * on demand. Everything else a face carries (opsz, GRAD, WONK, SOFT, ROND, the
 * Roboto Flex zoo) is recorded in `axes` as documentation only — `opsz` the
 * browser applies on its own, the rest sit at their defaults because nothing
 * sets font-variation-settings. They are listed so the next person can see what
 * a face is capable of before wiring a control to it.
 *
 * Loading is lazy by construction: a browser fetches a font file only when it
 * actually paints text in that family, so declaring ~20 `@font-face` rules costs
 * nothing until a face is *selected* (or previewed while the modal is open). The
 * runtime cost is the chosen faces, not the library. This is why we can ship
 * variety without eager-bundling everything (unlike `next/font`, which is right
 * for the always-loaded default UI face and wrong for an opt-in library).
 *
 * Two entries carry no library file. `inherit` means "follow the interface
 * font", which is the sane default for the peer name and for prose. `inter` is
 * the always-loaded next/font face (client/web/lib/fonts.ts, served from
 * public/Inter) — it stays out of the library so its ~700K of roman+italic is
 * not shipped twice.
 */

export type FontFallback = 'sans-serif' | 'serif' | 'monospace';

/** Which shelf of the selection modal a face sits on. */
export type FontShelf = 'sans' | 'serif' | 'mono' | 'display';

export type FontFace = {
  /** Stable slug stored in preferences + used as the file basename. */
  key: string;
  /** Human label shown in the modal. */
  label: string;
  /** CSS `font-family` name declared by our `@font-face` (null for the two
   *  entries that resolve to an existing family instead). */
  family: string | null;
  /** Generic fallback appended after the family. */
  fallback: FontFallback;
  /** The modal's grouping. */
  shelf: FontShelf;
  /** Public path to the upright face file, or null for `inherit` / `inter`. */
  file: string | null;
  /** Public path to a real italic file, when the family ships one and the face
   *  is one you would set a document in. A face with a `slnt` axis needs none
   *  (see `style`); a face with neither leaves the browser to synthesise. */
  italicFile?: string;
  /** `font-weight` descriptor — the file's real `wght` range. */
  weight?: string;
  /** `font-stretch` descriptor — the file's real `wdth` range. The older
   *  spelling of `font-width`, and the one every browser that can render Mantle
   *  already accepts. */
  stretch?: string;
  /** `font-style` descriptor for a `slnt` axis, as an oblique range. Note the
   *  sign flip the importer applies: OpenType measures slant counter-clockwise,
   *  CSS measures it clockwise. */
  style?: string;
  /** Axes with no CSS descriptor, for documentation. */
  axes?: string[];
};

const LIB = '/fonts/library';

/** The default for each of the four slots. "Default" is the ABSENCE of the
 *  stored value and of the CSS var — see resolveFontVars. */
export const DEFAULT_UI_FONT = 'inter';
export const DEFAULT_LOGO_FONT = 'bricolage-grotesque';
export const DEFAULT_TITLE_FONT = 'inherit';
export const DEFAULT_PROSE_FONT = 'inherit';

/**
 * Keys that used to exist and no longer do resolve to nothing, which every
 * caller already treats as "fall back to the default" — trimming the library
 * has always been safe. `sans` is the one exception worth mapping rather than
 * dropping: it was the old name for "follow the interface font" and was the
 * shipped default for the peer name, so a brain that stored it explicitly
 * should keep the behaviour it chose, not silently acquire a concrete face.
 */
