/** Modal shelf order + labels. Keys are the `shelf` values. */
export const FONT_SHELVES: Array<{ id: FontShelf; label: string }> = [
  { id: 'sans', label: 'Sans' },
  { id: 'serif', label: 'Serif' },
  { id: 'mono', label: 'Mono' },
  { id: 'display', label: 'Display' },
];

/**
 * ── Size ────────────────────────────────────────────────────────────────────
 *
 * One vocabulary for all four slots, applied two different ways.
 *
 * The INTERFACE size scales the ROOT font-size, and because the shell is
 * rem-based (h-16 header, rem paddings, rem control heights) the whole
 * interface scales rather than just the letters — the same thing OS display
 * scaling does. Percentages, not px, so a visitor who has raised their
 * browser's default font size keeps that as the baseline; hard-coding 18px
 * would quietly OVERRIDE an accessibility setting with our own.
 *
 * The other three are local multipliers on one element's own size, published as
 * CSS vars. A wordmark that scaled the shell would be a bug, not a feature.
 */
export type FontSize = 'xsmall' | 'small' | 'medium' | 'large';

export const FONT_SIZES: Array<{ id: FontSize; label: string; hint: string }> = [
  { id: 'xsmall', label: 'Extra small', hint: 'Densest' },
  { id: 'small', label: 'Small', hint: 'Denser — more on screen' },
  { id: 'medium', label: 'Medium', hint: 'Default' },
  { id: 'large', label: 'Large', hint: 'Roomier — easier to read' },
];

export const DEFAULT_FONT_SIZE: FontSize = 'medium';

/**
 * All four sizes travel as `<html>` ATTRIBUTES, never as resolved numbers.
 * app.css owns the multipliers, exactly as it already owned the root font-size
 * percentages, so there is one place holding the scale and no chance of a TS
 * copy drifting from the CSS that actually paints. "Default" is the absence of
 * the attribute.
 */
export function resolveFontSize(v: string | null | undefined): FontSize {
  return v === 'xsmall' || v === 'small' || v === 'large' || v === 'medium' ? v : DEFAULT_FONT_SIZE;
}

// ── lookup ──────────────────────────────────────────────────────────────────

/** How many variable axes a face carries: the CSS-addressable descriptors
 *  (weight/stretch/style) plus the descriptorless axes. The dialog's "· N axes"
 *  label and the test's two-axis-floor assertion both count through here, so
 *  the number users see is the same one the invariant enforces. */
export function axisCount(f: FontFace): number {
  return [f.weight, f.stretch, f.style].filter(Boolean).length + (f.axes?.length ?? 0);
}

const BY_KEY = new Map(FONT_LIBRARY.map((f) => [f.key, f]));

export function fontByKey(key: string | null | undefined): FontFace | undefined {
  if (!key) return undefined;
  return BY_KEY.get(LEGACY_KEYS[key] ?? key);
}

/**
 * CSS `font-family` value for a font key. Unknown keys → null (caller keeps its
 * default).
 */
export function fontFamilyValue(key: string | null | undefined): string | null {
  const f = fontByKey(key);
  if (!f) return null;
  // 'inherit' means "follow the interface font, whatever it is", so it resolves
  // through the var the interface choice overrides.
  if (f.key === 'inherit') return 'var(--font-sans, ui-sans-serif, sans-serif)';
  // 'inter' is a CONCRETE face, not "the current one". It must NOT resolve
  // through --font-sans: that var is what the interface choice overrides, so an
  // Inter row would preview in whichever face is selected — Saira under a label
  // saying Inter. `--font-sans-base` always holds the next/font Inter family,
  // set unconditionally in the root layout precisely so this stays truthful.
  if (f.key === DEFAULT_UI_FONT) return 'var(--font-sans-base, ui-sans-serif, sans-serif)';
  if (!f.family) return null;
  return `"${f.family}", ${f.fallback}`;
}

/**
 * `@font-face` rules for every library face, injected once server-side (root
 * layout + the share/print shell) so the declarations are present on first
 * paint (no FOUT wait) yet the files stay lazily fetched. Deterministic (no
 * runtime state) so it is safe to render into a <style>.
 */
export function displayFontFaceCss(): string {
  const rules: string[] = [];
  for (const f of FONT_LIBRARY) {
    if (!f.file || !f.family) continue;
    rules.push(face(f, f.file, f.style ?? 'normal'));
    // A real italic file is a SECOND face on the same family, distinguished
    // only by font-style — that is how the browser picks it for italic text.
    // Faces with a slnt axis get nothing extra: their one rule already
    // declares an oblique range, which covers italic.
    if (f.italicFile) rules.push(face(f, f.italicFile, 'italic'));
  }
  return rules.join('\n');
}

function face(f: FontFace, file: string, style: string): string {
  return (
    `@font-face{font-family:"${f.family}";` +
    `src:url("${file}") format("${fileFormat(file)}");` +
    `font-display:swap;` +
    `font-style:${style};` +
    (f.weight ? `font-weight:${f.weight};` : '') +
    (f.stretch ? `font-stretch:${f.stretch};` : '') +
    `}`
  );
}

/** `format()` hint for a face file. A wrong hint makes the browser skip the
 *  face entirely, so it is derived from the filename, never assumed. */
function fileFormat(file: string): string {
  if (file.endsWith('.woff2')) return 'woff2';
  if (file.endsWith('.woff')) return 'woff';
  if (file.endsWith('.otf')) return 'opentype';
  return 'truetype';
}

/**
 * Resolve the four stored font keys to their CSS `font-family` values, dropping
 * defaults and unknown keys — the shared projection behind the server-rendered
 * `<html>` appearance attributes (see appearance.ts). Values land as inline
 * style on the root element; "default" is the absence of the var, so the
 * elements' var() fallbacks win. There is deliberately NO localStorage /
 * before-paint-script path: the document arrives correct, and the client
 * providers read the rendered attributes back as their initial state.
 */
export type ResolvedFontVars = {
  wordmark?: string;
  pageTitle?: string;
  ui?: string;
  prose?: string;
};

export function resolveFontVars(
  logo: string | null | undefined,
  title: string | null | undefined,
  ui?: string | null | undefined,
  prose?: string | null | undefined,
): ResolvedFontVars {
  const out: ResolvedFontVars = {};
  if (logo && fontByKey(logo)?.key !== DEFAULT_LOGO_FONT) {
    const v = fontFamilyValue(logo);
    if (v) out.wordmark = v;
  }
  if (title && fontByKey(title)?.key !== DEFAULT_TITLE_FONT) {
    const v = fontFamilyValue(title);
    if (v) out.pageTitle = v;
  }
  // The UI font overrides `--font-sans` itself rather than introducing a var of
  // its own, so everything that already resolves it — the `font-sans` utility
  // and every element inheriting from the root — follows the choice with no
  // further wiring. Custom properties inherit, so setting it once at the root
  // is the whole mechanism.
  //
  // 'inherit' (and the legacy 'sans' that aliases to it) must be REJECTED for
  // this slot, not resolved: its value is `var(--font-sans, …)`, and stamping
  // that as --font-sans is a self-referential custom property — invalid at
  // computed-value time regardless of the fallback, which drops the ENTIRE
  // interface to the browser default font. The dialog never offers it for this
  // slot, but the PUT route is shape-only validation, so the stored value can
  // be anything.
  if (ui) {
    const key = fontByKey(ui)?.key;
    if (key !== DEFAULT_UI_FONT && key !== 'inherit') {
      const v = fontFamilyValue(ui);
      if (v) out.ui = v;
    }
  }
  if (prose && fontByKey(prose)?.key !== DEFAULT_PROSE_FONT) {
    const v = fontFamilyValue(prose);
    if (v) out.prose = v;
  }
  return out;
}
